css:
/* 矩形にする */
.block{text-align:justify; text-justify:inter-ideograph; line-break:strict; font-feature-settings:"palt" 1; letter-spacing:.08em; line-height:2.1; max-width:22em}
/* 行を手で決める */
.poem p{font-size:13px; line-height:2.4; letter-spacing:.08em; margin:0}
.poem p+p{margin-top:0}
.poem+.poem{margin-top:2.6em}
/* 折返し位置の固定（Safariでも効く） */
.nb{display:inline-block}
h2.mincho{font-family:"Yu Mincho",serif; letter-spacing:.28em; line-height:1.9}
